code.formula:
@Command([EditDocument];"1");

@If ((Type = "End of Contract" | Type = "Retired" | Type="End of Fixed Term Contract") & ContractStatus =""; @Return(@Do(@Command([EditGotoField];"ContractStatus") ;@Prompt([Ok];"Missing Value"; "Please indicate the contract status!")));"");
@If (Type="Resigned" & ResignedDate = ""; @Return(@Do(@Command([EditGotoField];"ResignedDate") ;@Prompt([Ok];"Missing Value"; "Please select the resignation date!")));"");
@If (Type="Others" & othertype = ""; @Return(@Do(@Command([EditGotoField];"othertype") ;@Prompt([Ok];"Missing Value"; "Please state the type!")));"");

@If(dtOriDeactivate = ""; @Return(@Do(@Command([EditGotoField];"dtOriDeactivate") ;@Prompt([Ok];"Missing Value"; "Please select date to deactivate the system access!")));"");
@If(dtOriDeactivate < @Today; @Return(@Do(@Command([EditGotoField];"dtOriDeactivate") ;@Prompt([Ok];"Missing Value"; "The 'Date to deactivate' CANNOT be earlier than  today!")));"");
@If(TypeCheck=0 & dtOriDeactivate > LastWorkingDay; @Return(@Do(@Command([EditGotoField];"dtOriDeactivate") ;@Prompt([Ok];"Missing Value"; "The 'Date to deactivate' must be not later than 'Last Working Day'!")));"");

@If (HOD = ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please select the HOD's email address!")));"");
@If (DivHead = ""; @Return(@Do(@Command([EditGotoField];"DivHead") ;@Prompt([Ok];"Missing Value"; "Please select the Division Head email address!")));"");

FIELD Body := "Please click on Extend Date button, if you would like to EXTEND the deactivation date before IT deactivate the system access as per the 'Date to deactivate system access'." + @NewLine +	"No action required, if no extension needed." + @NewLine;

@PostedCommand([FileSave]);

FIELD SubmitDate := @Now;
FIELD CA := "Submitted";
FIELD dtDeactivate := dtOriDeactivate;

tempTo := @If(isEI="1";AllIT:EI;AllIT);

@If(TypeCheck="0" & EmpEmail!="";@MailSend(EmpEmail;NULL;NULL;"Employee Exit Notification : " + EmpName+ " - " + @Text(dtOriDeactivate);NULL;"Please fill up the Exit Interview via this doclink  ------> ";[IncludeDoclink]);NULL);
@If(TypeCheck="1";
@MailSend(tempTo;HOD:DivHead:BCC;NULL;"Employee Exit Notification : " + Type + " - " + EmpName+ " - " + @Text(dtOriDeactivate);NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);
@MailSend(HOD:tempTo;DivHead:BCC;NULL;"Employee Exit Notification : " + Type + " - " + EmpName+ " - " + @Text(dtOriDeactivate);Body;"Please follow this doclink  ------> ";[IncludeDoclink]));

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If(dtDeactivate = "";@Return(@Do(@Command([EditGotoField];"dtDeactivate") ;@Prompt([Ok];"Missing Value"; "Please state the Extended Date before proceeding!")));"");

@If(dtDeactivate = dtOriDeactivate;@Return(@Do(@Command([EditGotoField];"dtDeactivate") ;@Prompt([Ok];"Missing Value"; "Please state the Extended Date before proceeding!")));"");

@If(Justification = "";@Return(@Do(@Command([EditGotoField];"Justification") ;@Prompt([Ok];"Missing Value"; "Please state the Justification before proceeding!")));"");

@If(dtDeactivate < @Today ; @Failure("The 'Date to Deactivate' must be earlier than  today");dtDeactivate > LastWorkingDay;@Failure("The 'Date to deactivate' must be later than 'Last Working Day' ") ;@Success);

@Command([FileSave]);

FIELD ExtName	:= @Name([CN];@UserName);
FIELD ExtDate 	:= @Now;
FIELD CA 			:= "Extended";

@MailSend(ED;DocAuthor;NULL;"Employee Exit Notification : Extended - " + EmpName+ " - " + @Text(dtDeactivate);NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (WDReason = ""; @Return(@Do(@Command([EditGotoField];"WDReason") ;@Prompt([Ok];"Missing Value"; "Please enter the reason before proceeding!")));"");

FIELD WDBy := @Name([CN];@UserName);
FIELD WDDate := @Now;
FIELD WDStatus :="Withdrawn";
FIELD CA := "Withdrawn";

@PostedCommand([FileSave]);

@MailSend(AllIT;NULL;NULL;"Employee Exit Notification : Withdrawn";NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

par.button:
@Command([EditDocument]; "1");

@If(ActualLWD= "";@Return(@Do(@Command([EditGotoField];"ActualLWD");@Prompt([Ok];"Missing Value"; "Please select the date!")));"");
@If(ActualLWD>RemDate;@Return(@Do(@Command([EditGotoField];"ActualLWD");@Prompt([Ok];"Missing Value"; "The date cannot be later than 'Date to deactivate system access'!")));"");

FIELD SentBy := @V3UserName;
FIELD SentDate := @Today ;

@MailSend(AllIT;HOD;NULL;"Employee Exit Notification : " + Type + " - " + EmpName+ " - " + @Text(ActualLWD);"Please disable all the access by " + @Text(ActualLWD) + @NewLine;"Please follow this doclink  ------> ";[IncludeDoclink]);

