@If(CompanyProperties = ""; @Return(@Do(@Command([EditGotoField];"CompanyProperties") ;@Prompt([Ok];"Missing Value"; "Please select the returned items!")));"");
@If(@Member("Others";CompanyProperties) != 0 & ReasonItems = ""; @Return(@Do(@Command([EditGotoField];"ReasonItems") ;@Prompt([Ok];"Missing Value"; "Please specify other  returned items!")));"");

